import{_ as o,o as e,c as d,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"로그 읽는 법","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/logs"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/logs"}],["meta",{"property":"og:title","content":"로그 읽는 법"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/logs.md","filePath":"docs/logs.md"}'),r={name:"docs/logs.md"};function a(n,t,l,s,g,i){return e(),d("div",null,[...t[0]||(t[0]=[c('<h1 id="로그-읽는-법" tabindex="-1">로그 읽는 법 <a class="header-anchor" href="#로그-읽는-법" aria-label="Permalink to &quot;로그 읽는 법&quot;">​</a></h1><p>로그는 워커와 세션이 자기가 한 일을 시각과 함께 한 줄씩 적어 둔 파일입니다. 셋이 있고, 무엇이 궁금한지에 따라 여는 파일이 다릅니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;루트&gt;/workers/runner.log                        디스패치 기록</span></span>\n<span class="line"><span>&lt;루트&gt;/workers/logs/&lt;시각&gt;-&lt;워커&gt;-&lt;해시&gt;.log      세션별 실제 출력</span></span>\n<span class="line"><span>&lt;루트&gt;/workers/cron.log                          cron 자체의 리다이렉트</span></span></code></pre></div><h2 id="runner-log-—-디스패치-기록" tabindex="-1"><code>runner.log</code> — 디스패치 기록 <a class="header-anchor" href="#runner-log-—-디스패치-기록" aria-label="Permalink to &quot;`runner.log` — 디스패치 기록&quot;">​</a></h2><p>워커가 tick마다 무엇을 했는지 여기 남깁니다. 형식은 <code>&lt;시각&gt; [&lt;워커이름&gt;] &lt;메시지&gt;</code>이고, 메시지는 접두어로 갈립니다.</p><table tabindex="0"><thead><tr><th>접두어</th><th>언제</th><th>뜻</th></tr></thead><tbody><tr><td><code>DISPATCH</code></td><td>티켓을 잡아 세션을 띄운 순간</td><td><code>kind</code>·<code>persona</code>·<code>sid</code>·세션 로그 파일명을 같이 적는다</td></tr><tr><td><code>DONE</code></td><td>세션이 정상 종료</td><td>실제 <code>session_id</code>를 적는다</td></tr><tr><td><code>FAIL</code></td><td>세션이 오류로 끝남</td><td>rc≠0 또는 응답의 <code>is_error</code></td></tr><tr><td><code>TIMEOUT</code></td><td><code>TICKET_MAXRUN</code> 초과로 강제종료</td><td>rc가 143/137일 때</td></tr><tr><td><code>STALL</code></td><td>엔진이 최초 프롬프트를 못 받음</td><td><code>TICKET_FEED_TIMEOUT</code> 초과</td></tr><tr><td><code>NOTE</code></td><td>세션키 정정</td><td>응답의 실제 <code>session_id</code>가 사전 발급값과 다를 때</td></tr><tr><td><code>SKIP</code></td><td>이번 tick을 건너뜀</td><td>같은 워커가 앞 세션을 아직 쥐고 있을 때</td></tr><tr><td><code>WARN</code></td><td>정지시키지 않는 이상 상황</td><td>스테일 락 회수·컨텍스트 경로 없음·페르소나 프로필 없음 등</td></tr><tr><td><code>ERROR</code></td><td>디스패치 준비 단계에서 실패</td><td>네 지점 중 하나 — <code>select</code> 실패·<code>assign</code> 실패·작업 디렉터리(<code>TICKET_CWD</code>) 없음·<code>mkfifo</code> 실패</td></tr><tr><td><code>REAP</code> / <code>REAP-FAIL</code></td><td>스테일 티켓을 백로그로 회수(또는 회수 실패)</td><td>매 tick 맨 앞</td></tr><tr><td><code>ASK</code></td><td>답변 요청으로 전환</td><td>자동 회수 3회째, 또는 세션이 <code>## 블록</code>을 남기고 멈췄으면 횟수와 무관하게 즉시. 본문에 <code>## 질문 n</code>이 붙는다</td></tr><tr><td><code>SUSPECT</code></td><td>손 클레임 세션이 유휴로 의심됨(보고만)</td><td>자동 회수하지 않는다</td></tr><tr><td><code>UNASSIGN</code> / <code>UNASSIGN-DENY</code></td><td>할당 해제 성공(또는 산 세션이라 거부)</td><td><code>unassign</code> 명령</td></tr><tr><td><code>AUTH 대기</code></td><td>헤드리스 토큰 없음</td><td>최초 1회만 남긴다</td></tr></tbody></table><p>&quot;아무 일도 안 일어나는 것 같다&quot;의 첫 확인 자리가 여기입니다. <code>DISPATCH</code>가 안 찍혔다면 디스패치 자체가 안 된 것이고(선정 실패·인증 대기 등), <code>DISPATCH</code> 뒤에 <code>DONE</code>도 <code>FAIL</code>도 없다면 세션이 아직 도는 중입니다.</p><h2 id="logs-시각-워커-해시-log-—-세션별-실제-출력" tabindex="-1"><code>logs/&lt;시각&gt;-&lt;워커&gt;-&lt;해시&gt;.log</code> — 세션별 실제 출력 <a class="header-anchor" href="#logs-시각-워커-해시-log-—-세션별-실제-출력" aria-label="Permalink to &quot;`logs/&lt;시각&gt;-&lt;워커&gt;-&lt;해시&gt;.log` — 세션별 실제 출력&quot;">​</a></h2><p><code>runner.log</code>가 &quot;언제 어떤 티켓을 물었나&quot;라면 이 파일은 &quot;그 세션 안에서 무슨 일이 있었나&quot;입니다. 엔진의 표준에러와 최종 표준출력이 여기 쌓입니다. 기본 엔진(<code>claude -p</code>, 스트리밍 입력)에서는 JSONL 한 줄이 곧 한 이벤트고, 마지막 <code>&quot;type&quot;:&quot;result&quot;</code> 줄이 그 세션의 최종 판정입니다(<code>FAIL</code>/<code>DONE</code> 판정의 근거).</p><p><code>FAIL</code>이나 <code>TIMEOUT</code>이 <code>runner.log</code>에 찍혔을 때 왜 실패했는지는 이 파일에서만 보입니다. <code>runner.log</code>는 판정 결과만 적고, 세션이 실제로 무엇을 읽고 무엇을 시도하다 막혔는지는 여기 담깁니다.</p><p>도는 동안에는 이 파일이 비어 있습니다. 워커가 엔진 출력을 따로 받아 두었다가 세션이 끝난 뒤 한 번에 붓기 때문입니다. 진행중인 세션을 실시간으로 보시려면 티켓 상세의 세션 스트림을 여세요. 그 화면이 읽는 것은 이 파일이 아니라 트랜스크립트, 그러니까 Claude Code가 자기 세션이 주고받은 말과 도구 호출을 순서대로 적어 두는 기록 파일입니다(<a href="/docs/screens">화면에서 보는 것</a> §세션 스트림).</p><h2 id="cron-log-—-워커-스크립트-자체의-출력" tabindex="-1"><code>cron.log</code> — 워커 스크립트 자체의 출력 <a class="header-anchor" href="#cron-log-—-워커-스크립트-자체의-출력" aria-label="Permalink to &quot;`cron.log` — 워커 스크립트 자체의 출력&quot;">​</a></h2><p>crontab 줄이 리다이렉트하는 대상입니다(<code>&gt;&gt; .../cron.log 2&gt;&amp;1</code>). 여기 쌓이는 것은 워커 <strong>셸 스크립트 자체</strong>의 표준출력·표준에러이지 세션의 출력이 아닙니다. 정상 동작 중에는 대개 비어 있습니다. <code>tick.sh</code>가 하는 일은 전부 <code>runner.log</code>에 따로 적으니까요. 이 파일에 뭔가 있다면 <code>bash</code> 자체가 실행되지 못했거나(권한, 셔뱅 오류) <code>tick.sh</code>가 시작하기도 전에 죽은 것입니다.</p><h2 id="증상별-확인-순서" tabindex="-1">증상별 확인 순서 <a class="header-anchor" href="#증상별-확인-순서" aria-label="Permalink to &quot;증상별 확인 순서&quot;">​</a></h2><ol><li><strong>아무 일도 안 일어난 것 같다</strong> → <code>runner.log</code>부터 보세요. <code>DISPATCH</code>가 있는지, 있다면 그 뒤에 <code>DONE</code>/<code>FAIL</code>/<code>TIMEOUT</code>이 붙었는지 봅니다.</li><li><strong><code>runner.log</code>조차 갱신되지 않는다</strong> → <code>cron.log</code>를 보세요. 워커 자체가 안 뜬 것입니다 (마운트 문제는 <a href="/docs/troubleshooting">트러블슈팅</a> §워커가 아예 안 뜬다 참고).</li><li><strong><code>FAIL</code>/<code>TIMEOUT</code>은 찍혔는데 이유를 알아야 한다</strong> → 그 줄의 <code>log=</code> 파일명으로 <code>logs/</code>의 세션별 로그를 여세요.</li></ol><p>다음은 <a href="/docs/analytics">사용 통계와 끄는 법</a>입니다.</p>',16)])])}const u=o(r,[["render",a]]);export{h as __pageData,u as default};
